import{_ as s,C as l,o as d,c as p,a2 as o,b as i,w as t,a as c,E as a,a3 as n}from"./chunks/framework.CDA9RsCr.js";const y=JSON.parse('{"title":"Backend Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/architecture/backend.md","filePath":"en/architecture/backend.md","lastUpdated":1794581028000}'),h={name:"en/architecture/backend.md"};function m(u,e,b,g,v,A){const r=l("Mermaid");return d(),p("div",null,[e[2]||(e[2]=o('<h1 id="backend-architecture" tabindex="-1">Backend Architecture <a class="header-anchor" href="#backend-architecture" aria-label="Permalink to &quot;Backend Architecture&quot;">​</a></h1><h2 id="entry-point-main-go" tabindex="-1">Entry point: main.go <a class="header-anchor" href="#entry-point-main-go" aria-label="Permalink to &quot;Entry point: main.go&quot;">​</a></h2><p><code>application.New</code> registers one service (<code>application.NewService(app.New())</code>), embeds the frontend dist and app icon, and creates a 1200×800 webview window (URL <code>/</code>). It also swaps in <code>devbridge.New(appSvc)</code> as the transport, so the desktop window uses Wails IPC while a browser tab uses the HTTP bridge.</p>',3)),(d(),i(n,null,{default:t(()=>[a(r,{id:"mermaid-9",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20M%20as%20main.go%0A%20%20%20%20participant%20A%20as%20application%0A%20%20%20%20participant%20AS%20as%20AppService%0A%20%20%20%20participant%20BR%20as%20devbridge.Transport%0A%20%20%20%20participant%20FS%20as%20frontend%20dist%0A%0A%20%20%20%20M-%3E%3EA%3A%20application.New(Options%7BServices%2C%20Assets%2C%20Transport%7D)%0A%20%20%20%20A-%3E%3EA%3A%20embed%20frontend%2Fdist%20and%20appicon%0A%20%20%20%20A-%3E%3EAS%3A%20ServiceStartup%0A%20%20%20%20AS-%3E%3EAS%3A%20load%20config.json%20%2F%20state.json%0A%20%20%20%20AS-%3E%3EAS%3A%20build%20wailsEmitter%2C%20inject%20into%20live%2Fprofile%0A%20%20%20%20A-%3E%3EBR%3A%20ServeAssets%20(starts%20%3A9246%20only%20with%20Vite%20attached)%0A%20%20%20%20A-%3E%3EFS%3A%20create%201200%C3%97800%20webview%20window%20(URL%20%2F)%0A%20%20%20%20Note%20over%20A%2CFS%3A%20runtime%3A%20frontend%20calls%20the%20same%20services%20via%20bindings%20or%20%2Fapi%0A%20%20%20%20A-%3E%3EAS%3A%20ServiceShutdown%0A%20%20%20%20AS-%3E%3EAS%3A%20stop%20danmaku%20feed%20and%20draw%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><code>ApplicationShouldTerminateAfterLastWindowClosed</code> returns false when <code>FRONTEND_DEVSERVER_URL</code> is set, keeping the process (and the browser bridge) alive during Vite debugging.</p><h2 id="app-layer-wails-boundary" tabindex="-1">app layer (Wails boundary) <a class="header-anchor" href="#app-layer-wails-boundary" aria-label="Permalink to &quot;app layer (Wails boundary)&quot;">​</a></h2><p><code>AppService</code> is the single service exposed to the frontend. It owns six services and <code>app *application.App</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>auth</code></td><td><code>*service.AuthService</code></td><td>login, account info, cookie persistence</td></tr><tr><td><code>live</code></td><td><code>*service.LiveLotteryService</code></td><td>draw lifecycle, participant pool, drawing</td></tr><tr><td><code>danmaku</code></td><td><code>*service.DanmakuFeedService</code></td><td>single-room live danmaku feed</td></tr><tr><td><code>emote</code></td><td><code>*service.EmoteService</code></td><td>emote map</td></tr><tr><td><code>profile</code></td><td><code>*service.ProfileService</code></td><td>profiles, rooms, background, history</td></tr><tr><td><code>room</code></td><td><code>*service.RoomService</code></td><td>room metadata and play URL</td></tr></tbody></table><ul><li><code>ServiceStartup</code>: loads <code>~/.luckydraw/config.json</code> and <code>state.json</code>, gets the app via <code>application.Get()</code>, builds <code>wailsEmitter</code> and injects it into <code>live</code>/<code>profile</code> (<code>auth</code> needs no events).</li><li><code>ServiceShutdown</code>: stops <code>danmaku</code>, then <code>live</code>.</li><li><code>ServiceName</code> returns <code>&quot;App&quot;</code>.</li></ul>',5)),(d(),i(n,null,{default:t(()=>[a(r,{id:"mermaid-119",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20FE%5B%22Frontend%20(webview)%22%5D%0A%20%20%20%20%20%20%20%20UI%5BReact%20components%20%2F%20hooks%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20APP%5B%22internal%2Fapp%20%C2%B7%20Wails%20boundary%22%5D%0A%20%20%20%20%20%20%20%20AS%5B%22AppService%3Cbr%2F%3Ethin%20delegation%22%5D%0A%20%20%20%20%20%20%20%20WE%5B%22wailsEmitter%3Cbr%2F%3Eimplements%20event.Emitter%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SVC%5B%22internal%2Fservice%20%C2%B7%20pure%20business%22%5D%0A%20%20%20%20%20%20%20%20Auth%5BAuthService%5D%0A%20%20%20%20%20%20%20%20Live%5BLiveLotteryService%5D%0A%20%20%20%20%20%20%20%20Dm%5BDanmakuFeedService%5D%0A%20%20%20%20%20%20%20%20Emote%5BEmoteService%5D%0A%20%20%20%20%20%20%20%20Prof%5BProfileService%5D%0A%20%20%20%20%20%20%20%20Room%5BRoomService%5D%0A%20%20%20%20end%0A%0A%20%20%20%20UI%20--%20%22AppService.*%20%2F%20%2Fapi%2F*%22%20--%3E%20AS%0A%20%20%20%20AS%20--%3E%20Auth%0A%20%20%20%20AS%20--%3E%20Live%0A%20%20%20%20AS%20--%3E%20Dm%0A%20%20%20%20AS%20--%3E%20Prof%0A%20%20%20%20AS%20--%3E%20Room%0A%20%20%20%20Dm%20--%3E%20Emote%0A%20%20%20%20Live%20--%20%22emitter.Emit%20live%3Auser_join%22%20--%3E%20WE%0A%20%20%20%20Prof%20--%20%22emitter.Emit%20profile%3Aswitched%2Fcreated%22%20--%3E%20WE%0A%20%20%20%20WE%20-.%20%22application.Event.Emit%22%20.-%3E%20UI%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><code>wailsEmitter</code> implements <code>event.Emitter</code> by delegating to <code>application.App.Event.Emit</code>; services never import Wails.</p><h2 id="service-layer-pure-business" tabindex="-1">service layer (pure business) <a class="header-anchor" href="#service-layer-pure-business" aria-label="Permalink to &quot;service layer (pure business)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Dependencies</th><th>Notes</th></tr></thead><tbody><tr><td><code>AuthService</code></td><td><code>*bili.Client</code>, <code>*config.Config</code>, configPath</td><td>validates a stored cookie on startup; clears it on <code>-101</code>/<code>-400</code></td></tr><tr><td><code>LiveLotteryService</code></td><td><code>*live.LiveLottery</code>, <code>Emitter</code>, <code>func() *bili.Client</code></td><td>connects rooms, starts/stops draws, emits <code>live:user_join</code></td></tr><tr><td><code>DanmakuFeedService</code></td><td><code>*bili.Client</code>, <code>*EmoteService</code></td><td>per-room feed, 200-line ring buffer, cursor-based reads</td></tr><tr><td><code>EmoteService</code></td><td><code>*bili.Client</code></td><td>reply emotes plus room emotes, cached 6 hours</td></tr><tr><td><code>ProfileService</code></td><td><code>*config.RuntimeState</code>, statePath, <code>Emitter</code></td><td>profile CRUD, rooms, background, history (100 per profile)</td></tr><tr><td><code>RoomService</code></td><td><code>func() *bili.Client</code></td><td>room info and play URL, cached 45 seconds</td></tr></tbody></table><p>Things worth remembering:</p><ul><li><strong>Collecting danmaku and running a draw are separate pipelines.</strong> <code>DanmakuFeedService</code> only powers the right-hand panel and connects per room; <code>LiveLotteryService</code> opens its own connections for the participant pool. Switching the previewed room never disturbs a running draw.</li><li><strong>The feed is cursor-based.</strong> The frontend polls with <code>since</code>, and the server returns only newer lines, so nothing is rendered twice.</li><li><strong>Emotes are merged server-side.</strong> Global reply emotes load first, then the current room&#39;s emotes layer on top; the frontend only maps <code>[name]</code> tokens to images.</li><li><strong>History is written in the <code>app</code> layer.</strong> After <code>DrawWinners</code> succeeds, <code>AppService</code> calls <code>profile.AddHistory</code>; a failure is stashed in <code>lastHistoryError</code> and read once by the frontend.</li></ul><h2 id="events-and-config" tabindex="-1">Events and config <a class="header-anchor" href="#events-and-config" aria-label="Permalink to &quot;Events and config&quot;">​</a></h2><ul><li><code>event.Emitter.Emit(name string, data ...any) bool</code>, implemented by <code>app.wailsEmitter</code>.</li><li>Events: <code>live:user_join</code> (new participant), <code>profile:switched</code>, <code>profile:created</code>.</li></ul><table tabindex="0"><thead><tr><th>Type</th><th>Contents</th><th>File</th></tr></thead><tbody><tr><td><code>Config</code></td><td><code>{Cookie}</code></td><td><code>~/.luckydraw/config.json</code></td></tr><tr><td><code>RuntimeState</code></td><td><code>{Profiles, ActiveProfile}</code></td><td><code>~/.luckydraw/state.json</code></td></tr><tr><td><code>ProfileConfig</code></td><td><code>{ID, Name, BackgroundImage, WatchedRooms, Keyword, WinnerCount, History}</code></td><td>inside state.json</td></tr><tr><td><code>HistoryRecord</code></td><td><code>{ID, Keyword, WinnerCount, Time, Winners}</code></td><td>inside state.json</td></tr></tbody></table><p>Both files are written with <code>0600</code> inside a <code>0700</code> directory. <code>migrateOldState</code> upgrades the legacy single-profile layout.</p><h2 id="live-bili-login" tabindex="-1">live / bili / login <a class="header-anchor" href="#live-bili-login" aria-label="Permalink to &quot;live / bili / login&quot;">​</a></h2><ul><li><code>bili</code>: HTTP client plus <code>SignWBI</code>. <code>GetMyInfo</code> returns the account; WBI keys come from <code>web-interface/nav</code> and are cached.</li><li><code>live</code>: <ul><li><code>types.go</code> — protocol constants and data shapes (16-byte header, ops 2/3/5/7/8).</li><li><code>protocol.go</code> — packet framing, including zlib-compressed bodies.</li><li><code>room_auth.go</code> — room info and danmaku hosts (WBI-signed, <code>wss_port</code> first).</li><li><code>parse.go</code> — <code>DANMU_MSG</code>, enter/follow messages and emote tokens.</li><li><code>client.go</code> — connect, authenticate, heartbeat, reconnect backoff.</li><li><code>lottery.go</code> — UID-deduplicated participant pool and Fisher-Yates draw.</li></ul></li><li><code>login</code>: the QR flow <code>GetQRCode</code> / <code>CheckQRCodeStatus</code>; status <code>0</code> success, <code>86038</code> expired, <code>86090</code> scanned awaiting confirmation.</li></ul><p>Handshake notes: <code>getDanmuInfo</code> requires WBI signing (<code>w_rid</code> / <code>wts</code>). The handshake packet must carry the logged-in <code>uid</code>, <code>key</code> and <code>buvid3</code> (fetched from <code>frontend/finger/spi</code> when the cookie lacks it), otherwise Bilibili masks nicknames and zeroes <code>uid</code>, collapsing every viewer into one participant.</p><h2 id="browser-bridge-internal-devbridge" tabindex="-1">Browser bridge: internal/devbridge <a class="header-anchor" href="#browser-bridge-internal-devbridge" aria-label="Permalink to &quot;Browser bridge: internal/devbridge&quot;">​</a></h2><p><code>Transport</code> wraps Wails&#39; default <code>HTTPTransport</code> and adds a JSON API:</p><table tabindex="0"><thead><tr><th>Route</th><th>Method</th><th>Capability</th></tr></thead><tbody><tr><td><code>/api/session</code></td><td>GET</td><td>login state and account</td></tr><tr><td><code>/api/login</code>, <code>/api/login/qr</code></td><td>POST</td><td>cookie login, QR login</td></tr><tr><td><code>/api/logout</code></td><td>POST</td><td>log out</td></tr><tr><td><code>/api/qr</code>, <code>/api/qr/status</code></td><td>GET</td><td>QR code and polling</td></tr><tr><td><code>/api/rooms</code></td><td>GET / POST / DELETE</td><td>list, add, remove rooms</td></tr><tr><td><code>/api/rooms/info</code>, <code>/api/rooms/play</code></td><td>GET</td><td>room info, play URL</td></tr><tr><td><code>/api/lottery/connect</code>, <code>/start</code>, <code>/stop</code>, <code>/draw</code></td><td>POST</td><td>connect, start, stop, draw</td></tr><tr><td><code>/api/lottery/status</code></td><td>GET</td><td>run state and participants (also the bridge probe)</td></tr><tr><td><code>/api/lottery/history-error</code></td><td>GET</td><td>read-and-clear the last history write error</td></tr><tr><td><code>/api/danmaku/watch</code></td><td>POST</td><td>subscribe to a room&#39;s danmaku</td></tr><tr><td><code>/api/danmaku</code></td><td>GET / DELETE</td><td>poll with <code>since</code>, stop</td></tr><tr><td><code>/api/danmaku/emotes</code></td><td>GET</td><td>emote map</td></tr><tr><td><code>/api/clipboard</code></td><td>POST</td><td>native clipboard fallback</td></tr></tbody></table><p><code>APIHandler()</code> exposes those routes on their own, and <code>cmd/devbridge</code> mounts exactly that handler, so the standalone binary and the Wails dev transport behave identically. The bridge only listens on <code>127.0.0.1:9246</code> when <code>FRONTEND_DEVSERVER_URL</code> is set, retrying 20 times to tolerate a previous process still holding the port.</p><h2 id="frontend-visible-methods" tabindex="-1">Frontend-visible methods <a class="header-anchor" href="#frontend-visible-methods" aria-label="Permalink to &quot;Frontend-visible methods&quot;">​</a></h2><p>Every <code>AppService</code> method, callable via generated bindings or the matching <code>/api</code> route.</p><table tabindex="0"><thead><tr><th>Method</th><th>Area</th><th>Description</th></tr></thead><tbody><tr><td><code>Login</code> / <code>LoginWithQRCode</code></td><td>auth</td><td>validate and persist the cookie</td></tr><tr><td><code>GetQRCode</code> / <code>CheckQRCodeStatus</code></td><td>auth</td><td>QR generation and polling</td></tr><tr><td><code>IsLoggedIn</code> / <code>GetAccountInfo</code> / <code>Logout</code></td><td>auth</td><td>session state</td></tr><tr><td><code>ConnectLiveRooms</code> / <code>StartLiveLottery</code> / <code>StopLiveLottery</code></td><td>live</td><td>draw lifecycle; start returns connection results</td></tr><tr><td><code>DrawWinners</code> / <code>GetParticipantCount</code> / <code>IsLiveLotteryRunning</code></td><td>live</td><td>draw, count, run state</td></tr><tr><td><code>GetLastHistoryError</code> / <code>CopyText</code></td><td>live</td><td>history error, native clipboard</td></tr><tr><td><code>WatchDanmaku</code> / <code>StopDanmaku</code> / <code>GetDanmakuFeed</code> / <code>GetEmoteMap</code></td><td>danmaku</td><td>live danmaku panel</td></tr><tr><td><code>GetRoomInfo</code> / <code>GetRoomPlayURL</code></td><td>room</td><td>room metadata and HLS URL</td></tr><tr><td><code>GetProfiles</code> / <code>SwitchProfile</code> / <code>CreateProfile</code> / <code>DeleteProfile</code> / <code>RenameProfile</code></td><td>profile</td><td>profile management</td></tr><tr><td><code>SaveProfileConfig</code> / <code>SetBackgroundImage</code> / <code>GetBackgroundImage</code></td><td>profile</td><td>keyword, count, background</td></tr><tr><td><code>AddWatchedRoom</code> / <code>RemoveWatchedRoom</code> / <code>GetWatchedRooms</code></td><td>profile</td><td>room management</td></tr><tr><td><code>GetHistory</code> / <code>DeleteHistory</code> / <code>DeleteAllHistory</code> / <code>ExportHistory</code></td><td>history</td><td>read, delete, export</td></tr></tbody></table><p>Methods returning structured data return JSON strings that the frontend parses with <code>parseJSON</code>; that&#39;s what lets both transports share one frontend API layer.</p>',20))])}const S=s(h,[["render",m]]);export{y as __pageData,S as default};
